import json, re

def parse_multiroot_json(path):
    with open(path) as f:
        content = f.read()
    # Split on }{ boundaries
    parts = re.split(r'\}\s*\{', content)
    results = []
    for i, part in enumerate(parts):
        if i > 0: part = '{' + part
        if i < len(parts)-1: part = part + '}'
        results.append(json.loads(part))
    return results

def extract_packages(data_list):
    pkgs = {}
    for data in data_list:
        for proj in data.get('projects', []):
            pname = proj['path'].split('/')[-1]
            for fw in proj.get('frameworks', []):
                for pkg in fw.get('topLevelPackages', []):
                    key = (pname, pkg['id'])
                    pkgs[key] = (pkg.get('requestedVersion',''), pkg.get('resolvedVersion',''))
